INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Garden Pub', 'You have just acquired an old pub in a small gnomish village, and now all you have to do is get it cleaned up and ready to serve the whole village! You barely have enough room to serve a handful of customers, so you must build up your reputation and gold in order to stock your pub and expand your dining area.' FROM games WHERE igdb_id = 117449 ON CONFLICT (game_id, language_code) DO NOTHING;
