INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('viv-and-bob', 134947, '2019-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8h2z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scszpt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viv and Bob', 'Viv and Bob is a puzzle game made with GB Studio 1.1 where you play Viv and Bob, trying to exit the many rooms of the mansion''s basement. While Bob is strong enough to push blocks to their designated places, Lil Viv is light enough to walk above insecure parts of the floor. Bob and Viv are trapped in two sides of a mirror. The room Bob is standing in is a mirrored version of Viv''s room and vice versa. Actions on one side of the mirror affect the other side as well. Switch between both protagonists and always think about both sides of the mirror.' FROM games WHERE igdb_id = 134947 ON CONFLICT (game_id, language_code) DO NOTHING;
