INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breeza Budgie Bill', 'Breeza Budgie Bill is Part 3d Platformer, and Part 3rd Person Shooter. inspired by early 3d games of the mid 90''s, Budgie Bill is a definitive assault parakeet!!!, on a mission to defeat all who oppose him, with the Help of Pumpkin Dog, Budgie Bill has a boost ability that can be turned on and off.' FROM games WHERE igdb_id = 122608 ON CONFLICT (game_id, language_code) DO NOTHING;
