INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mr-yo-yo', 269162, '2019-09-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co75ju.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Yo-Yo', 'You control Mr. Yo-Yo. You are given five lives at the start of the game – one in play, and another four in reserve. The object of the game is to descend to the bottom of the cave, and rescue the Notelies by returning them to the top of the cave. When a Notely is ready to be rescued, he will appear in the little bucket area at the bottom of the cave. To pick up the Notely, descend to the bottom of your string. Mr. Yo-Yo will begin flashing various colors to indicate you’ve picked up a Notely. Then, return to the top of the screen to release the Notely to freedom! Mr. Yo-Yo will then return to his normal color, and you can get ready to rescue the next Notely. Sometimes, you may have to shoot some enemies to get the Notelies to appear. The further you get into a level of caves, the more timid the Notelies become. You’ll have to shoot more and more enemies for them to have enough courage to appear.
