INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris Gems', 'Tetris Gems is an all-new Tetris game variant designed to both challenge and entertain puzzle fans. Whether you''re new to Tetris or a seasoned expert, Tetris Gems rewards players for clearing lines and uncovering Gems. An added element of luck helps level the playing field, making Tetris Gems the perfect puzzler for all Tetris fans.' FROM games WHERE igdb_id = 158991 ON CONFLICT (game_id, language_code) DO NOTHING;
