INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last AntLion', 'The Queen Ant doesn''t like filthy half-ant, half-lion hybrids like you living in her nefarious kingdom. She has made it her life''s mission to eradicate your kind from the earth. It''s time to get revenge and redeem your fallen comrades. YOU are The Last AntLion. Can you survive?' FROM games WHERE igdb_id = 120753 ON CONFLICT (game_id, language_code) DO NOTHING;
