INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emberlight', 'Emberlight is a true roguelike dungeon crawler, set in a world where the Gods have given you a great gift - and a great curse. Explore procedurally generated dungeons as a Knight of the Ember Order. Conquer the quests set out before your party, and uncover the lore of the land.' FROM games WHERE igdb_id = 118207 ON CONFLICT (game_id, language_code) DO NOTHING;
