INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minotaur Hotel', 'A traveler is suddenly gifted the deed to a hotel by an old man with a troubled mind. Upon arriving, however, the hotel''s new master finds the building empty of guests and in a state of heavy decay. But he is not alone—within the halls of the hotel lives Asterion, the Minotaur of Cretan mythology, damned by the gods to forever serve the master''s every command. An in-development visual novel with light management mechanics.' FROM games WHERE igdb_id = 166032 ON CONFLICT (game_id, language_code) DO NOTHING;
