INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The StoryTale', 'The StoryTale - is a fairy tale platformer where everything goes bing-bang-boom, but everybody remain alive and healthy. It''s a game where you constantly forget the spells and the weapons are cursed. But even in the midst of the swirling action you can stop and think over the next step.' FROM games WHERE igdb_id = 36467 ON CONFLICT (game_id, language_code) DO NOTHING;
