INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Vraz', 'The Legend of Vraz features a fun filled exciting gameplay of 6-9 hours amidst fantasy worlds created with stunning hand painted 2D art and inhabited by mesmerizing characters. The highlight of the game is its exquisite hand painted 2D graphics in traditional Indian miniature painting style and a mesmerizing game play that give game enthusiasts an outstanding adventure experience. The stunning visuals combined with an incredible soundtrack and an enchanting game play captivate the player and make the player wander in a magnificent dreamland from where they would hate to come back.' FROM games WHERE igdb_id = 54298 ON CONFLICT (game_id, language_code) DO NOTHING;
