INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Basketball Dunk!', 'Basketball Dunk is a one-button game where the objective is to hit a key to dunk a ball down into the hoop. The balls are flying from the sides of the screen and, with each successful dunk, the challenge increases as the hoop changes its position or starts moving as well. The game is over once the player misses even one dunk.' FROM games WHERE igdb_id = 378108 ON CONFLICT (game_id, language_code) DO NOTHING;
