INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resurrection', 'Resurrection is a seamless map horizontal 3D action game. The map is large and multi-branch plot has many endings. It can kill the NPC to unlock the hidden equipment, but the corresponding hidden plot and the hidden boss can not be unlocked. There are more than 20 different weapons, multi-stage manoeuvres, magic and divinity.' FROM games WHERE igdb_id = 284263 ON CONFLICT (game_id, language_code) DO NOTHING;
