INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer Pinball', 'Have a soccer match with your friend or family member on the pinball field! You will try to score as many as possible within 3-minutes to see who is the best. You can see the top 4 high scores and beating them will get harder because after each round, there will be an additional ball in the field! Also your mini audience will always cheer for you.' FROM games WHERE igdb_id = 80790 ON CONFLICT (game_id, language_code) DO NOTHING;
