INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cricket Through the Ages', 'Swing bats and throw balls through the intertwined histories of humankind and cricket in this one button, physics-driven game. Over a thousand years ago the human race teetered on the edge of extinction. Our ancestors were helpless against the mighty behemoths of the land. And then, salvation…the game of cricket was invented! Go alone, or take a friend, on a journey through the rich and exquisitely accurate history of cricket in Cricket Through the Ages.' FROM games WHERE igdb_id = 124398 ON CONFLICT (game_id, language_code) DO NOTHING;
