INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('prepare-the-first-rpg-village-the-adventures-of-nyanzou-and-kumakichi-escape-game-series', 173143, '2019-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3z5a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar150e.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prepare the First RPG Village: The Adventures of Nyanzou&Kumakichi - Escape Game Series', 'We find ourselves in some RPG World. The Devil suddenly shows up. People fall into great misery. But, that’s when one young man makes a stand. He comes to be known as the Hero. He leaves the First Castle, heading for the First Village nearby. Leaving that aside for now, the First Village is very busy getting ready to welcome the Hero-sama. Looks like Nyanzou and Kumakichi, who live in the village, are also going to help out with the preparations. It''s your standard escape game, on the easy side, and highly recommended for beginners. It comes with autosave, hints, and memo functions.' FROM games WHERE igdb_id = 173143 ON CONFLICT (game_id, language_code) DO NOTHING;
