INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In the Pause Between the Ringing', 'In the Pause between the Ringing is a rumination about completion, about territorial margins and about the haunting of bodies and memories that are translated across borders. It is an adaption of an unpublished story written by Mir Umar Hassan for the editor of the Malwa Chronicle in the July of 1958.' FROM games WHERE igdb_id = 117898 ON CONFLICT (game_id, language_code) DO NOTHING;
