INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lionkiller', 'Play as Hua Mulan, a young lesbian who is conscripted into the First Opium War against the British Empire. Run a flower shop, kiss a girl, shoot a matchlock rifle, and uncover a military conspiracy! Your actions will lead you to one out of four different endings. Will you get the girl, or will you die an inglorious death?' FROM games WHERE igdb_id = 138256 ON CONFLICT (game_id, language_code) DO NOTHING;
