INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eggy Car', 'Eggy Car is a fun and challenging physics-based driving game where your goal is to transport a fragile egg across bumpy roads without breaking it. Unlike traditional racing games that focus on speed, Eggy Car requires precision and control to keep the egg from falling. Navigate through hills, gaps, and obstacles, collect coins to unlock better cars, and use power-ups like the diamond freeze to help you travel farther. Every run is a test of balance and patience, making it an addictive game for players of all skill levels. How far can you go without cracking the egg?' FROM games WHERE igdb_id = 335654 ON CONFLICT (game_id, language_code) DO NOTHING;
