INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle Rodok', 'Castle Rodok is an action-RPG game with heavy emphasis on adventure and PSX style retro graphics. In Castle Rodok, you create your own character from five different races, and try to survive at least 8 levels of it''s procedurally generated dungeons. There are three levels which the dungeons can occur in: Wintery forest, castle dungeons and the castle itself. After the 8 levels, you have a chance to find the final bossfight...' FROM games WHERE igdb_id = 349479 ON CONFLICT (game_id, language_code) DO NOTHING;
