INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Useless Box: The Game', 'This game is exactly like a Useless Box but better because it''s a video game about hitting a switch on a Useless Box (still no purpose). Want to spend hours flipping a switch and accomplishing nothing? This game is for you! As an added bonus, the box will tell you stories as well as reveal unlocks!' FROM games WHERE igdb_id = 126615 ON CONFLICT (game_id, language_code) DO NOTHING;
