INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '70 Seconds! Adventure', '70 Seconds! Adventure - a game where you have to wander around the locations in search of a way out of here. You will have to overcome the intricate locations filled with aggressive monsters and various bosses. Choose your weapon and arm yourself with it and go to a dangerous world. Destroy aggressive bosses, find funny references and Easter eggs, meet different achivki and find new weapons. Go through an adventure that you will remember forever.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 121777 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
