INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aero Attack: Retro Space Shooter', 'Aero Attack is a retro shooter arcade game where you play as a pilot named Bob, tasked to defend the human race from various aerial minions. Fly his shooting plane through space, dodge the floating minions, alien bosses, satellites, and a couple of space cows. The game aimed to make people feel nostalgic and sentimental, remembering the retro games everyone loved spending time on and the emotions they stirred in us.' FROM games WHERE igdb_id = 115715 ON CONFLICT (game_id, language_code) DO NOTHING;
