INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dogfighter: World War 2', 'A dogfighting game set in the skies of World War II featuring the famous fighter planes of the time, including the Zero fighter plane, Mustang, Spitfire, Messerschmitt, and more! Become a pilot of World War II and experience historic dogfights in the Scenario Mode. Compete in 40-player battles with options to play solo, a duo (two-person team), or in a squad (three-person team) inBattle Royale Mode.' FROM games WHERE igdb_id = 102866 ON CONFLICT (game_id, language_code) DO NOTHING;
