INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('slabwell-the-quest-for-kaktuns-alpaca', 124402, '2019-04-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ass.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/araux.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SlabWell: The Quest For Kaktun''s Alpaca', 'Somewhere deep in the Amazon jungle, lies the finest treasure mankind has ever crafted: The Jade Alpaca. Professional thief duo Sam and Jacky head off on an adventure to recover the mythical artifact, determined to solve the riddles and overcome the challenges that have kept it safe through centuries. An original puzzle adventure: Put your mind to test as you explore Kaktun’s pyramid, where you’ll find over 100 handcrafted levels full of traps, enigmas and a host of new mechanics with every step. A brothers tale: Follow the story of Sam and Jacky in their dream to become the world’s wealthiest thieves, as they face their worst fears in their hardest heist yet. Cooperative mode: Join forces with friends and family to solve custom cooperative levels, where communication will be your most valuable tool. An engaging journey: Explore the wonders of a long lost temple, from its corridors reclaimed by nature to its majestic treasure chambers, accompanied by the game’s beautiful soundtrack.' FROM games WHERE igdb_id = 124402 ON CONFLICT (game_id, language_code) DO NOTHING;
