INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Fear: The Free World', 'Age of Fear is a seven-year old turn-based strategy series that marries a tabletop wargame with elements of RPG. Age of Fear: The Free World serves as introduction to the series. You can roam the Open World realm, develop their party, find powerful relics and participate in a variety of quests!' FROM games WHERE igdb_id = 111940 ON CONFLICT (game_id, language_code) DO NOTHING;
