INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nubla-2', 118539, '2019-01-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co50dt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar13tp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nubla 2', 'Nubla 2 continues the adventure of the characters we met in Nubla Episode 1 from the end of their boat trip. Once in the continent, they must begin their search for the City in the Center of the World, looking to return the memory to that world, now lost. But getting there will not be easy. The City is not a physical place: It is beyond the dreams and the trip will definitely be hard and dangerous for our characters, who now have not only Nubla to achieve their goal but with many other characters and inhabitants of that world will be finding in their way.
