INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RFS: Real Flight Simulator', 'RFS: Real Flight Simulator lets player experience flying in any part of the world and exploring sceneries and airports in high resolution with satellite maps, 3D buildings, runways, procedures and air traffic. User can Jump on board of real time flights, chat with other pilots and join them in multiplayer. He can manage flight plans and interact with ATC controllers. Get access to thousands of community created liveries, customize all airplanes, their gauges, failures and weather conditions.' FROM games WHERE igdb_id = 144649 ON CONFLICT (game_id, language_code) DO NOTHING;
