INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uh Oh Bartender', 'In Uh Oh Bartender, you take the role of a bartender at Cypher''s, the hottest new bar and grill. However, the drinks served at Cypher''s aren''t just drinks, they are also puzzles! In order to serve these drinks, you will have to decipher their ingredients based on rules found inside the procedurally generated names!' FROM games WHERE igdb_id = 122297 ON CONFLICT (game_id, language_code) DO NOTHING;
