INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution A20', 'Dance Dance Revolution A20 (pronounced Ace Two Oh) is a music video game, the 16th installment of the Dance Dance Revolution series, and the sequel to Dance Dance Revolution A. The game was released on new, golden cabinets on March 20, 2019 in Japan. A software upgrade for older cabinets for Japan and Asia was released on July 24, 2019, with Korea receiving a localized release on August 1, 2019, and North America on September 24, 2019. A location test in Europe began on October 7, 2019, and ended on March 16, 2020. Dance Dance Revolution A20 Plus is an update that adds 14 new songs, available on July 1, 2020 for Japanese 20th Anniversary cabinets.' FROM games WHERE igdb_id = 124446 ON CONFLICT (game_id, language_code) DO NOTHING;
