INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stamp Boy', 'Stamp Boy is a retro style puzzle-platformer game about hero save princess from evil monster with only his stamp ability. Make your way further and further to get close to the evil monster and defeat bosses. And also collect Orbs in every level to unlock something unknow. No random generation in the world, every levels are by handwork.' FROM games WHERE igdb_id = 118080 ON CONFLICT (game_id, language_code) DO NOTHING;
