INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cribbage JD', 'The classic card game Cribbage Online also known as Crib, Cribble, and Noddy. A multiplayer card game traditionally for two players, that involves playing and grouping cards in combinations which gain points. Cribbage has several distinctive features: the cribbage board used for score keeping, the crib, box, or kitty, a separate hand counting for the dealer, two distinct scoring stages (the play and the show), aces low, and a unique scoring system including points for groups of cards that total fifteen. Cribbage is a Trump style Card game.' FROM games WHERE igdb_id = 144781 ON CONFLICT (game_id, language_code) DO NOTHING;
