INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gundam Battle: Gunpla Warfare', 'Get ready for the next battle! The first mobile Gundam game is here to bring the best sci-fi anime mecha action to the palm of your hands! Gundam Battle: Gunpla Warfare is a 3D mecha action battle game based off the popular science fiction manga series. Build your custom Gundam plastic model (aka Gunpla) and take it into battle against other Gunpla builders to win the Gunpla Battle Tournament!' FROM games WHERE igdb_id = 120305 ON CONFLICT (game_id, language_code) DO NOTHING;
