INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roterra: Flip the Fairytale', 'Can you find your way in a world where the ground shifts under your feet with every move? Slide and rotate cubes in this gravity-defying world to find the correct path for Princess Angelica and her friends. Flip the world and you may just discover that the journey matters far more than the destination – and that stereotypes are not to be trusted.
