INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dobutsu-shogi-world', 120260, '2019-06-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57el.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9xe.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dobutsu Shogi World', 'Master Shogi easily with this game! Let’s play and learn Shogi on three levels! Dobutsu Shogi (Age: 4+) A game played on a 3×4 square board with eight animal pieces. Cute animal pieces have marks to show the direction of movement. Easy rules. Have fun learning basic Shogi! Goro-Goro Dobutsu Shogi (Age: 5+) A game played on a 5×6 square board with 16 animal pieces. An advanced Dobutsu Shogi game. The perfect way to learn and increase your skill in moving Dog (Gold) and Cat (Silver) that are important pieces for protecting King and for checkmating. Dobutsu Shogi in the Greenwood (Age: 6+) A game played on a 9×9 square board with 40 animal pieces. A board game with the same rules as Shogi. Piece movement and other basic rules are the same as Dobutsu Shogi and Goro-Goro Dobutsu Shogi. Use all that you learned and start playing Shogi.' FROM games WHERE igdb_id = 120260 ON CONFLICT (game_id, language_code) DO NOTHING;
