INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts: VR Experience', 'Announced in September 2018, Kingdom Hearts VR Experience is a free, 10-minute interactive video "featuring iconic moments [and music] from the Kingdom Hearts games" with the ability to unlock additional content by progressing through the experience. The first part was released in Japan on January 23, 2019, with the second part releasing in early 2019. The first part had initially been scheduled to release on January 18, 2019, after initial release dates of December 25, 2018 for the first part, with the second part releasing on January 18, 2019.' FROM games WHERE igdb_id = 109275 ON CONFLICT (game_id, language_code) DO NOTHING;
