INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Out the Window: a car trip sim', 'A cute & nostalgic car trip sim in which you can relive the long drives of your youth, complete with six choices of imaginary friend to run beside your car, three choices of radio station, and seven choices of gas station snack! The ride is topped with a healthy dose of media theory inspired by Wolfgang Schivelbusch''s analysis of the impact of motor vehicles on our perception of time, space, and landscape.' FROM games WHERE igdb_id = 134691 ON CONFLICT (game_id, language_code) DO NOTHING;
