INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon of Choices', 'Dungeon of Choices is a short game based on old gamebooks. You are playing as a mighty knight who goes into the dungeon to get the holy grail. But your journey won''t be easy. There''s a lot of danger and traps on your way. Of course, not all of the things are bad, but be prepared for hard trials! The end of your adventure depends just on your decisions trough all playtime.' FROM games WHERE igdb_id = 178859 ON CONFLICT (game_id, language_code) DO NOTHING;
