INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('idlequest', 360543, '2019-07-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa9g8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3zsb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IdleQuest', 'Click (or just sit back and watch) as your party of heroes battle to earn your gold. You can leave the game on so it plays while you sleep :D Use your gold to unlock new heroes and move to new and more dangerous areas. When you feel you are ready... ascend! Ascending will allow you to unlock new characters, and gives you more power to restart the game with.' FROM games WHERE igdb_id = 360543 ON CONFLICT (game_id, language_code) DO NOTHING;
