INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lonely', '《Lonely》 is a puzzle-platformer game, which contains 20 game levels. Players in the game have the ability to control time reversal. Players in the game should go back to the past, cooperate with themselves, and shuttle through parallel worlds in the game, so as to cross the platform, across the abyss and solve the puzzle switch to move...' FROM games WHERE igdb_id = 117347 ON CONFLICT (game_id, language_code) DO NOTHING;
