INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alchemic Dungeons DX', 'Alchemic Dungeons DX is an expanded and improved entry in the series. This deluxe version includes new characters, items and dungeons; even the background music has been enhanced! Dungeons are randomly generated and you progress with turn-based action. Every step you take will affect events, enemies and exploration. All of the action takes place within an awesome 8-bit aesthetic, with retro-style visuals and audio. With lots of characters and fresh areas to explore, get ready for the challenge in Alchemic Dungeons DX!' FROM games WHERE igdb_id = 115273 ON CONFLICT (game_id, language_code) DO NOTHING;
