INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brain Pump', 'Brain Pump is a puzzle game: you rotate the blocks to make horizontal or vertical rows, or 4 blocks in a square, to score. It trains your pattern-recognition while having fun, and lets you compete with other players in the highscores list. It''s cute, simple and effective for all ages, and it has little bonus game on board to relax from the puzzling once in a while. Fun to play and pretty addictive.' FROM games WHERE igdb_id = 116155 ON CONFLICT (game_id, language_code) DO NOTHING;
