INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chusingura-46-plus-1-wacchi-to-onii-chan-no-love-love-nagaya-seikatsu', 335756, '2019-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jg3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvrku.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ChuSingura 46+1 Wacchi to Onii-chan no Love Love Nagaya Seikatsu', 'Shinpachirou failed to stop the raid of the forty-seven ronin and returned to Naoto on the verge of death. Her injuries healed as they spent a quiet life together. As spring arrived, Suguha asked if she would like to live in Edo, to which she readily agreed. However, they were not samurai but rather ronin, and without money, they have no jobs. Still, they believed that they’ll be able to figure things out when they got there.They found a place in a cheap longhouse and she explained to him the various lifestyles and customs of the Edo period, much of which was a still a commonplace in the present age. Their loving cohabitation true story begins now.' FROM games WHERE igdb_id = 335756 ON CONFLICT (game_id, language_code) DO NOTHING;
