INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Escape', 'Think in 360 degrees in Alien Escape to solve challenges a dark tower offers. You are a group of aliens that were kidnapped and jailed. To escape you have to solve puzzles where you have to do more than just jumping and running! Change your gravity and manipulate different objects in each room. Gravity, fire, water and a lot more will challenge you so much, you have to think around the corner!' FROM games WHERE igdb_id = 116144 ON CONFLICT (game_id, language_code) DO NOTHING;
